package server

import (
	"chatapp/backend/cache"
	"chatapp/backend/config"
	"chatapp/backend/kafka"
	"chatapp/backend/log"
	"chatapp/backend/protocal"
	"github.com/gorilla/websocket"
	"github.com/gogo/protobuf/proto"
)

type ClientWs struct{
/*
	负责管理已经和服务器连接上的客户端，负责每个客户端的读和写
*/
	Conn *websocket.Conn
	Name string
	Send chan []byte
}

func (c *ClientWs) Read() {
	defer func() {
		AppServer.Unregister <- c
		c.Conn.Close()
	}()

	for {
		_, message, err := c.Conn.ReadMessage()
		if err != nil {
			log.Logger.Error("client read message error", log.Any("client read message error", err.Error()))
			AppServer.Unregister <- c
			c.Conn.Close()
			break
		}

		msg := &protocol.Message{}
		if err := proto.Unmarshal(message, msg); err != nil {
			log.Logger.Error("client unmarshal message error", log.Any("error", err))
			continue
		}
		if err := cache.RefreshUserOnline(c.Name); err != nil {
			log.Logger.Warn("refresh user online failed", log.String("user", c.Name), log.Any("error", err))
		}

		// pong
		if msg.Type == config.HEAT_BEAT {
			pong := &protocol.Message{
				Content: config.PONG,
				Type:    config.HEAT_BEAT,
			}
			pongByte, err2 := proto.Marshal(pong)
			if nil != err2 {
				log.Logger.Error("client marshal message error", log.Any("client marshal message error", err2.Error()))
			}
			if err := c.Conn.WriteMessage(websocket.BinaryMessage, pongByte); err != nil {
				log.Logger.Error("client write pong error", log.Any("error", err))
				break
			}
		} else {
			if config.GetConfig().Msg_trans_channel == config.KAFKA {
				if err := kafka.Send(message); err != nil {
					log.Logger.Error("kafka send failed, fallback go channel", log.Any("error", err))
					AppServer.Broadcast <- message
				}
			} else {
				AppServer.Broadcast <- message
			}
		}
	}
}

func (c *ClientWs) Write() {
	defer func() {
		c.Conn.Close()
	}()

	for message := range c.Send {
		if err := c.Conn.WriteMessage(websocket.BinaryMessage, message); err != nil {
			log.Logger.Error("client write message error", log.Any("error", err))
			break
		}
	}
}

package router

import (
	"chatapp/backend/handlers"
	"chatapp/backend/log"
	"chatapp/backend/model"
	"chatapp/backend/server"
	"net/http"
	"os"
	"strings"

	"github.com/gin-gonic/gin"
	"github.com/gorilla/websocket"
	"go.uber.org/zap"
)

var upGrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool {
		return true
	},
}

func RunSocekt(c *gin.Context) {
	user := strings.TrimSpace(c.Query("user"))
	if user == "" {
		c.JSON(http.StatusBadRequest, model.FailMsg("query 参数 user 不能为空"))
		return
	}
	log.Logger.Info("newUser", zap.String("newUser", user))
	ws, err := upGrader.Upgrade(c.Writer, c.Request, nil)
	if err != nil {
		log.Logger.Error("upgrade websocket failed", log.Any("error", err))
		return
	}

	client := &server.ClientWs{
		Name: user,
		Conn: ws,
		// 适度缓冲，避免广播时阻塞
		Send: make(chan []byte, 256),
	}

	server.AppServer.Register <- client
	go client.Read()
	go client.Write()
}

func NewRouter() *gin.Engine {
	gin.SetMode(gin.ReleaseMode)

	server := gin.Default()

	// Avoid stale front-end assets while iterating quickly in development.
	server.Use(func(c *gin.Context) {
		if strings.HasPrefix(c.Request.URL.Path, "/views/") {
			c.Header("Cache-Control", "no-store")
		}
		c.Next()
	})

	viewsDir := "views"
	if _, err := os.Stat(viewsDir); err != nil {
		viewsDir = "../views"
	}

	// serve static front-end assets under /views
	server.Static("/views", viewsDir)

	// redirect root to a useful page (index or demo)
	server.GET("/", func(c *gin.Context) {
		c.Redirect(http.StatusFound, "/views/index.html")
	})

	server.Use(Cors())
	server.Use(Recovery)

	group := server.Group("")
	{
		group.GET("/health", func(c *gin.Context) {
			c.JSON(http.StatusOK, model.SuccessMsg("ok"))
		})

		group.GET("/user/:uuid", handlers.GetUserDetails)
		group.GET("/user/name", handlers.GetUserByName)
		group.GET("/status/user/online", handlers.GetUserOnlineStatus)
		group.POST("/user/register", handlers.Register)
		group.POST("/user/login", handlers.Login)
		// group.PUT("/user", handlers.ModifyUserInfo)

		group.POST("/friend", handlers.AddFriend)

		// group.GET("/file/:fileName", handlers.GetFile)
		// group.POST("/file", handlers.SaveFile)

		group.POST("/group", handlers.CreateGroup)
		group.POST("/group/:uuid", handlers.CreateGroup)
		group.GET("/group/name", handlers.GetGroupByName)
		group.POST("/group/join/:userUuid/:groupUuid", handlers.JoinGroup)
		group.GET("/group/:groupUuid/history", handlers.GetGroupHistoryMessage)
		group.POST("/ai/chat", handlers.AIChat)

		group.GET("/ws", RunSocekt)
	}
	return server
}


func Cors() gin.HandlerFunc {
	return func(c *gin.Context) {
		method := c.Request.Method
		origin := c.Request.Header.Get("Origin") //请求头部
		if origin != "" {
			c.Header("Access-Control-Allow-Origin", "*") // 可将将 * 替换为指定的域名
			c.Header("Access-Control-Allow-Methods", "POST, GET, OPTIONS, PUT, DELETE, UPDATE")
			c.Header("Access-Control-Allow-Headers", "Origin, X-Requested-With, Content-Type, Accept, Authorization")
			c.Header("Access-Control-Expose-Headers", "Content-Length, Access-Control-Allow-Origin, Access-Control-Allow-Headers, Cache-Control, Content-Language, Content-Type")
			c.Header("Access-Control-Allow-Credentials", "true")
		}
		//允许类型校验
		if method == "OPTIONS" {
			c.JSON(http.StatusOK, "ok!")
		}

		defer func() {
			if err := recover(); err != nil {
				log.Logger.Error("HttpError", zap.Any("HttpError", err))
			}
		}()

		c.Next()
	}
}

func Recovery(c *gin.Context) {
	defer func() {
		if r := recover(); r != nil {
			log.Logger.Error("gin catch error: ", log.Any("gin catch error: ", r))
			c.JSON(http.StatusOK, model.FailMsg("系统内部错误"))
		}
	}()
	c.Next()
}

