   101→					s.sendRawMessage(msg.To, message)
   102→				}
   103→				continue
   104→			}
   105→
   106→			// 未指定接收方，进行广播
   107→			for id, conn := range s.Clients {
   108→				log.Logger.Info("allUser", log.Any("allUser", id))
   109→				select {
   110→				case conn.Send <- message:
   111→				default:
   112→					close(conn.Send)
